#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m17-lock-down-shelf pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m17-lock-down-shelf
CHECKS="probes-ready web-to-api api-to-db api-to-cache dns-from-web dns-from-db client-to-web web-to-db-denied web-to-cache-denied db-to-api-denied cache-to-db-denied client-to-api-denied client-to-db-denied api-available web-available"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m17-lock-down-shelf
checks:
  - id: probes-ready
    describe: The test Pods are running
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-probe
      - -o
      - jsonpath={.items[*].status.phase}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          matches: ^(Running ){3}Running$
    hint: The setup starts four probes (probe-web, probe-api, probe-db, probe-cache) and a client in the namespace outside. Run `kubectl get pods --namespace shelf`. The first setup pulls the busybox image from the internet.
  - id: web-to-api
    describe: web may connect to api on 8081
    kubectl:
      - exec
      - probe-web
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$API_SERVICE_HOST" 8081 || exit 7
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: "Both ends must allow it: an ingress rule on the Pods labeled app.kubernetes.io/component=api that lists web on TCP 8081, and an egress rule on web that lists api on TCP 8081. Run `kubectl describe networkpolicy --namespace shelf`."
  - id: api-to-db
    describe: api may connect to db on 5432
    kubectl:
      - exec
      - probe-api
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$DB_SERVICE_HOST" 5432 || exit 7
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: An ingress rule on db that lists api on TCP 5432, and an egress rule on api that lists db on TCP 5432.
  - id: api-to-cache
    describe: api may connect to cache on 6379
    kubectl:
      - exec
      - probe-api
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$CACHE_SERVICE_HOST" 6379 || exit 7
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: An ingress rule on cache that lists api on TCP 6379, and an egress rule on api that lists cache on TCP 6379.
  - id: dns-from-web
    describe: web may look up names (DNS egress to kube-dns)
    kubectl:
      - exec
      - probe-web
      - -n
      - shelf
      - --
      - sh
      - -c
      - nslookup -timeout=2 kubernetes.default.svc.cluster.local. 10.96.0.10 | grep -q "^Name" || exit 7
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: The default-deny egress policy blocks DNS too. Allow egress on UDP and TCP port 53 to the Pods labeled k8s-app=kube-dns in the namespace labeled kubernetes.io/metadata.name=kube-system, for every Pod of shelf (an empty podSelector).
  - id: dns-from-db
    describe: db may look up names (DNS egress to kube-dns)
    kubectl:
      - exec
      - probe-db
      - -n
      - shelf
      - --
      - sh
      - -c
      - nslookup -timeout=2 kubernetes.default.svc.cluster.local. 10.96.0.10 | grep -q "^Name" || exit 7
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: One DNS egress policy with an empty podSelector covers every Pod of the namespace, the db included.
  - id: client-to-web
    describe: A visitor from the namespace outside may connect to web on 8080
    kubectl:
      - exec
      - client
      - -n
      - outside
      - --
      - sh
      - -c
      - nc -z -w 2 web.shelf.svc.cluster.local. 8080 || exit 7
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: "The visitor is in another namespace, so only web's ingress needs a rule: a namespaceSelector on kubernetes.io/metadata.name=outside, on TCP 8080. Nothing in shelf selects the client, so it needs no egress rule."
  - id: web-to-db-denied
    describe: web may not connect to db
    kubectl:
      - exec
      - probe-web
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$DB_SERVICE_HOST" 5432 && exit 0; exit 7
    expect:
      exitCode: 7
    hint: web is not on the list of the db's ingress rules. Check that no policy of yours lists web as a peer of db, and that default-deny ingress exists.
  - id: web-to-cache-denied
    describe: web may not connect to cache
    kubectl:
      - exec
      - probe-web
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$CACHE_SERVICE_HOST" 6379 && exit 0; exit 7
    expect:
      exitCode: 7
    hint: Only api may reach cache. Check the peers of the ingress rule on cache.
  - id: db-to-api-denied
    describe: db may not connect to api
    kubectl:
      - exec
      - probe-db
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$API_SERVICE_HOST" 8081 && exit 0; exit 7
    expect:
      exitCode: 7
    hint: Policies allow one direction. The allow from web to api does not let db call api.
  - id: cache-to-db-denied
    describe: cache may not connect to db
    kubectl:
      - exec
      - probe-cache
      - -n
      - shelf
      - --
      - sh
      - -c
      - nc -z -w 2 "$DB_SERVICE_HOST" 5432 && exit 0; exit 7
    expect:
      exitCode: 7
    hint: Only api may reach db.
  - id: client-to-api-denied
    describe: The visitor may not connect to api
    kubectl:
      - exec
      - client
      - -n
      - outside
      - --
      - sh
      - -c
      - nc -z -w 2 api.shelf.svc.cluster.local. 8081 && exit 0; exit 7
    expect:
      exitCode: 7
    hint: The visitor may reach web only. Check that the namespaceSelector rule is on web's ingress and not on api's.
  - id: client-to-db-denied
    describe: The visitor may not connect to db
    kubectl:
      - exec
      - client
      - -n
      - outside
      - --
      - sh
      - -c
      - nc -z -w 2 db.shelf.svc.cluster.local. 5432 && exit 0; exit 7
    expect:
      exitCode: 7
    hint: "Only api may reach db. Check that default-deny ingress selects every Pod of the namespace (podSelector: {})."
  - id: api-available
    describe: "The api is available: it can look up names and reach the db"
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.status.availableReplicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "1"
    hint: The api's readiness probe fails while it cannot look up or reach the db, and the Pod leaves its Service. Allow its DNS lookups and its connection to the db. Run `kubectl get pods --namespace shelf` and `kubectl describe pod --namespace shelf -l app.kubernetes.io/name=shelf,app.kubernetes.io/component=api`.
  - id: web-available
    describe: The web is available
    kubectl:
      - get
      - deployment
      - shelf-web
      - -n
      - shelf
      - -o
      - jsonpath={.status.availableReplicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "1"
    hint: The web becomes ready when it can reach the api. Check the web-to-api allow and DNS.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
